
import csv
from pathlib import Path

from boa.config.database import engine
from boa.config.datasets import DATASETS, RAW_DATA_DIR


# Explicit source-column mappings.
# raw_row_id is generated by PostgreSQL and is intentionally excluded.
RAW_COLUMNS = {
    "customers": [
        "customer_id",
        "customer_unique_id",
        "customer_zip_code_prefix",
        "customer_city",
        "customer_state",
    ],
    "geolocation": [
        "geolocation_zip_code_prefix",
        "geolocation_lat",
        "geolocation_lng",
        "geolocation_city",
        "geolocation_state",
    ],
    "order_items": [
        "order_id",
        "order_item_id",
        "product_id",
        "seller_id",
        "shipping_limit_date",
        "price",
        "freight_value",
    ],
    "payments": [
        "order_id",
        "payment_sequential",
        "payment_type",
        "payment_installments",
        "payment_value",
    ],
    "reviews": [
        "review_id",
        "order_id",
        "review_score",
        "review_comment_title",
        "review_comment_message",
        "review_creation_date",
        "review_answer_timestamp",
    ],
    "orders": [
        "order_id",
        "customer_id",
        "order_status",
        "order_purchase_timestamp",
        "order_approved_at",
        "order_delivered_carrier_date",
        "order_delivered_customer_date",
        "order_estimated_delivery_date",
    ],
    "products": [
        "product_id",
        "product_category_name",
        "product_name_lenght",
        "product_description_lenght",
        "product_photos_qty",
        "product_weight_g",
        "product_length_cm",
        "product_height_cm",
        "product_width_cm",
    ],
    "sellers": [
        "seller_id",
        "seller_zip_code_prefix",
        "seller_city",
        "seller_state",
    ],
    "category_translation": [
        "product_category_name",
        "product_category_name_english",
    ],
}


def get_source_row_count(file_path: Path) -> int:
    """Count CSV data records, excluding the header."""
    with file_path.open("r", encoding="utf-8-sig", newline="") as file:
        reader = csv.reader(file)
        next(reader, None)
        return sum(1 for _ in reader)


def validate_csv_headers(file_path: Path, expected_columns: list[str]) -> None:
    """Ensure the source CSV has the expected columns in the expected order."""
    with file_path.open("r", encoding="utf-8-sig", newline="") as file:
        reader = csv.reader(file)
        actual_columns = next(reader, [])

    if actual_columns != expected_columns:
        raise ValueError(
            f"Header mismatch in {file_path.name}.\n"
            f"Expected: {expected_columns}\n"
            f"Actual:   {actual_columns}"
        )


def copy_csv_to_table(cursor, file_path: Path, table_name: str) -> int:
    """Stream a CSV file into a PostgreSQL table using COPY."""
    columns = RAW_COLUMNS[table_name]

    column_sql = ", ".join(f'"{column}"' for column in columns)

    copy_sql = (
        f"COPY raw.{table_name} ({column_sql}) "
        "FROM STDIN WITH (FORMAT CSV, HEADER TRUE, ENCODING 'UTF8')"
    )

    with file_path.open("rb") as file:
        with cursor.copy(copy_sql) as copy:
            while chunk := file.read(1024 * 1024):
                copy.write(chunk)

    return cursor.rowcount


def load_raw_data() -> list[dict]:
    """Transactionally reload all raw tables from the original CSV files."""
    results = []

    # Validate every file before modifying the database.
    for dataset_name, filename in DATASETS.items():
        file_path = RAW_DATA_DIR / filename

        if not file_path.exists():
            raise FileNotFoundError(f"Dataset not found: {file_path}")

        validate_csv_headers(file_path, RAW_COLUMNS[dataset_name])

    connection = engine.raw_connection()

    try:
        cursor = connection.cursor()

        try:
            # All nine tables are refreshed in one transaction.
            table_names = ", ".join(
                f"raw.{table_name}" for table_name in DATASETS
            )

            cursor.execute(
                f"TRUNCATE TABLE {table_names} RESTART IDENTITY"
            )

            for dataset_name, filename in DATASETS.items():
                file_path = RAW_DATA_DIR / filename

                source_count = get_source_row_count(file_path)

                copy_csv_to_table(
                    cursor=cursor,
                    file_path=file_path,
                    table_name=dataset_name,
                )

                cursor.execute(
                    f"SELECT COUNT(*) FROM raw.{dataset_name}"
                )
                database_count = cursor.fetchone()[0]

                result = {
                    "dataset": dataset_name,
                    "source_rows": source_count,
                    "database_rows": database_count,
                    "status": (
                        "PASSED"
                        if source_count == database_count
                        else "FAILED"
                    ),
                }

                results.append(result)

                if source_count != database_count:
                    raise ValueError(
                        f"Row count mismatch for {dataset_name}: "
                        f"source={source_count}, "
                        f"database={database_count}"
                    )

            connection.commit()

        except Exception:
            connection.rollback()
            raise

        finally:
            cursor.close()

    finally:
        connection.close()

    return results


def main() -> None:
    print("Starting raw data ingestion...\n")

    results = load_raw_data()

    print(
        f"{'DATASET':<22}"
        f"{'SOURCE ROWS':>15}"
        f"{'DATABASE ROWS':>17}"
        f"{'STATUS':>12}"
    )
    print("-" * 66)

    for result in results:
        print(
            f"{result['dataset']:<22}"
            f"{result['source_rows']:>15,}"
            f"{result['database_rows']:>17,}"
            f"{result['status']:>12}"
        )

    print("\nRaw ingestion completed successfully.")


if __name__ == "__main__":
    main()
